@dataclass(kw_only=True)
class ClosedTimeRangeStructure:
    """
    Data Type for a range of times.

    Both start and end time are required.

    :ivar start_time: The (inclusive) start time.
    :ivar end_time: The (inclusive) end time.
    """

    class Meta:
        target_namespace = "http://www.netex.org.uk/netex"

    start_time: XmlTime = field(
        metadata={
            "name": "StartTime",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )
    end_time: XmlTime = field(
        metadata={
            "name": "EndTime",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )


@dataclass(kw_only=True)
class ClosedTimestampRangeStructure:
    """
    Data Type for a range of date and times.

    Both start and end time are required.

    :ivar start_time: The (inclusive) start date and time.
    :ivar end_time: The (inclusive) end date and time.
    """

    class Meta:
        target_namespace = "http://www.netex.org.uk/netex"

    start_time: XmlDateTime = field(
        metadata={
            "name": "StartTime",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )
    end_time: XmlDateTime = field(
        metadata={
            "name": "EndTime",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )


