@dataclass(kw_only=True)
class KeyValueStructure:
    """
    Type for a Key List.

    :ivar key: Identifier of value e.g. System.
    :ivar value: Value for alternative key.
    :ivar type_of_key: Identifier of type of key.
    """

    class Meta:
        target_namespace = "http://www.netex.org.uk/netex"

    key: str = field(
        metadata={
            "name": "Key",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )
    value: str = field(
        metadata={
            "name": "Value",
            "type": "Element",
            "namespace": "http://www.netex.org.uk/netex",
        }
    )
    type_of_key: None | str = field(
        default=None,
        metadata={
            "name": "typeOfKey",
            "type": "Attribute",
        },
    )


